134	  /// Returns count of total number of plugins, number of Swift Package Manager compatible plugins,
135	  /// and number of CocoaPods compatible plugins. A plugin can be both Swift Package Manager and
136	  /// CocoaPods compatible.
137	  ///
138	  /// If [hostPlatformIsMacOS], prints warnings when using a plugin incompatible with the available
139	  /// Darwin Dependency Manager (Swift Package Manager or CocoaPods).
140	  ///
141	  /// If [hostPlatformIsMacOS], prints message prompting the user to deintegrate CocoaPods if
142	  /// using all Swift Package plugins.
143	  Future<({int totalCount, int swiftPackageCount, int podCount})> _evaluatePluginsAndPrintWarnings({
144	    required FlutterDarwinPlatform platform,
145	    required XcodeBasedProject xcodeProject,
146	    required bool hostPlatformIsMacOS,
147	  }) async {
148	    var pluginCount = 0;
149	    var swiftPackageCount = 0;
150	    var cocoapodCount = 0;
151	    final Set<String> cocoapodOnlyPlugins = {};
152	    for (final Plugin plugin in _plugins) {
153	      if (plugin.platforms[platform.name] == null) {
154	        continue;
155	      }
156	      final String? swiftPackagePath = plugin.pluginSwiftPackageManifestPath(
157	        _fileSystem,
158	        platform.name,
159	      );
160	      final bool swiftPackageManagerCompatible =
161	          swiftPackagePath != null && _fileSystem.file(swiftPackagePath).existsSync();
162	
163	      final String? podspecPath = plugin.pluginPodspecPath(_fileSystem, platform.name);
164	      final bool cocoaPodsCompatible =
165	          podspecPath != null && _fileSystem.file(podspecPath).existsSync();
166	
167	      // If a plugin is missing both a Package.swift and Podspec, it won't be
168	      // included by either Swift Package Manager or Cocoapods. This can happen
169	      // when a plugin doesn't have native platform code.
170	      // For example, image_picker_macos only uses dart code.
171	      if (!swiftPackageManagerCompatible && !cocoaPodsCompatible) {
172	        continue;
173	      }
174	
175	      pluginCount += 1;
176	      if (swiftPackageManagerCompatible) {
177	        swiftPackageCount += 1;
178	      }
179	      if (cocoaPodsCompatible) {
180	        cocoapodCount += 1;
181	      }
182	
183	      if (cocoaPodsCompatible && !swiftPackageManagerCompatible) {
184	        cocoapodOnlyPlugins.add(plugin.name);
185	      }
